-- Recursive common table expressions: the forms each server reads (anchors
-- and recursive parts, UNION ALL or DISTINCT, the column list), the types of
-- the columns (from the anchor alone?), the limit of the iterations, and the
-- constructs a recursive part may hold (aggregate, window, GROUP BY, ORDER BY,
-- LIMIT, DISTINCT, joins, subqueries, two references, mutual recursion).
-- MariaDB before 10.6 recurses up to 4,294,967,295 times, where some of
-- these cases never stop: measured from 10.6.
DROP TABLE IF EXISTS wr;
CREATE TABLE wr (id INT NOT NULL PRIMARY KEY, parent INT NULL, name VARCHAR(20) NOT NULL);
INSERT INTO wr VALUES (1, NULL, 'root'), (2, 1, 'a'), (3, 1, 'b'), (4, 2, 'c'), (5, 4, 'd');
-- Forms.
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION DISTINCT SELECT n % 2 + 1 FROM r) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION SELECT n % 2 + 1 FROM r) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT 10 UNION ALL SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT n + 10 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT 1) SELECT n FROM r ORDER BY n;
-- The order of the parts: MariaDB keeps the last of two anchors in a row
-- after a recursive part, and refuses two recursive parts after a first one.
WITH RECURSIVE r (n) AS (SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11 UNION ALL SELECT 1 UNION ALL SELECT 10) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11 UNION ALL SELECT 10) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT 1 UNION ALL SELECT n + 10 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT n + 10 FROM r WHERE n < 3 UNION ALL SELECT 1) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n % 2 + 1 FROM r UNION SELECT 1) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT 1 UNION ALL SELECT 1) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n + 1 FROM r WHERE n < 3 UNION ALL (SELECT 1 UNION ALL SELECT 10)) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11 UNION ALL SELECT n + 100 FROM r WHERE n < 2 UNION ALL SELECT 10) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT 10 UNION ALL SELECT n + 100 FROM r WHERE n < 2 UNION ALL SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11 UNION ALL SELECT 10 UNION ALL SELECT 20) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 OR n BETWEEN 10 AND 11 UNION ALL SELECT 10 UNION ALL SELECT n + 100 FROM r WHERE n < 2) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION SELECT n % 2 + 1 FROM r UNION SELECT 5) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT n % 2 + 1 FROM r UNION SELECT 1 UNION SELECT 5) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT 1) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL (SELECT n + 1 FROM r WHERE n < 3)) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS ((SELECT 1) UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE a (n) AS (SELECT 1), r (n) AS (SELECT n FROM a UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE a (n) AS (SELECT 1) SELECT n FROM a;
WITH r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT a.n, b.n FROM r AS a JOIN r AS b ON a.n = b.n ORDER BY a.n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r WHERE n IN (SELECT n FROM r) ORDER BY n;
SELECT * FROM (WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r) AS d ORDER BY n;
SELECT (WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT MAX(n) FROM r) AS m;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) TABLE r;
WITH RECURSIVE r (id, path) AS (SELECT id, CAST(name AS CHAR(200)) FROM wr WHERE parent IS NULL UNION ALL SELECT wr.id, CONCAT(r.path, '/', wr.name) FROM r JOIN wr ON wr.parent = r.id) SELECT id, path FROM r ORDER BY id;
-- Types: the anchor gives them?
WITH RECURSIVE r (n, s) AS (SELECT 1, 'a' UNION ALL SELECT n + 1, CONCAT(s, 'b') FROM r WHERE n < 3) SELECT n, s FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 0.5 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 127 UNION ALL SELECT n + 1 FROM r WHERE n < 129) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT NULL UNION ALL SELECT 1 FROM r WHERE n IS NULL) SELECT n FROM r;
WITH RECURSIVE r (d) AS (SELECT DATE '2024-01-30' UNION ALL SELECT d + INTERVAL 1 DAY FROM r WHERE d < '2024-02-01') SELECT d FROM r ORDER BY d;
WITH RECURSIVE r (d) AS (SELECT DATE '2024-01-30' UNION ALL SELECT d + INTERVAL 1 HOUR FROM r WHERE d < '2024-01-31') SELECT d FROM r ORDER BY d;
DROP TABLE IF EXISTS wr_types, wr_plain;
CREATE TABLE wr_types AS WITH RECURSIVE r (n, s, f, de, d, z, b, c) AS (SELECT 1, 'a', 1.5e0, 1.5, DATE '2024-01-30', NULL, 1 = 1, CAST(1 AS SIGNED) UNION ALL SELECT n + 1, s, f, de, d, z, b, c FROM r WHERE n < 2) SELECT * FROM r;
SHOW CREATE TABLE wr_types;
CREATE TABLE wr_plain AS SELECT 1 AS n, 'a' AS s, 1.5e0 AS f, 1.5 AS de, DATE '2024-01-30' AS d, NULL AS z, 1 = 1 AS b, CAST(1 AS SIGNED) AS c;
SHOW CREATE TABLE wr_plain;
DROP TABLE IF EXISTS wr_types, wr_plain, wr_columns;
CREATE TABLE wr_columns AS WITH RECURSIVE r (n, i, u, t, v, e, eu, ei) AS (SELECT 1, id, CAST(1 AS UNSIGNED), CAST(1 AS DECIMAL(3)), CAST(name AS CHAR(5)), IF(FALSE, -9223372036854775807, 1), IF(FALSE, 18446744073709551615, CAST(1 AS UNSIGNED)), IF(FALSE, -9223372036854775807, id) FROM wr WHERE id = 1 UNION ALL SELECT n + 1, i, u, t, v, e, eu, ei FROM r WHERE n < 2) SELECT * FROM r;
SHOW CREATE TABLE wr_columns;
DROP TABLE IF EXISTS wr_columns;
-- A column keeps its type: an INT overflows in both.
WITH RECURSIVE r (n) AS (SELECT id FROM wr WHERE id = 1 UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT n FROM r ORDER BY n;
-- The emulation of a BIGINT anchor towards MariaDB.
WITH RECURSIVE r (n) AS (SELECT IF(FALSE, -9223372036854775807, 1) UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT IF(FALSE, -9223372036854775807, id) FROM wr WHERE id = 1 UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT IF(FALSE, 18446744073709551615, CAST(1 AS UNSIGNED)) UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 2147483647 UNION ALL SELECT n + 1 FROM r WHERE n < 2147483648) SELECT n FROM r;
WITH RECURSIVE r (n) AS (SELECT CAST(1 AS SIGNED) UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 0.4 FROM r WHERE n < 2) SELECT COUNT(*) FROM r;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 0.6 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (s) AS (SELECT 'ab' UNION ALL SELECT 'c' FROM r WHERE s = 'ab') SELECT s, LENGTH(s) FROM r ORDER BY s;
WITH RECURSIVE r (n) AS (SELECT NULL UNION ALL SELECT 1 FROM r WHERE n IS NULL) SELECT n, n IS NULL, LENGTH(n) FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT NULL UNION ALL SELECT NULL FROM r WHERE n IS NOT NULL) SELECT n FROM r;
-- The limit of the iterations.
SELECT @@cte_max_recursion_depth;
SELECT @@max_recursive_iterations;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 1000) SELECT COUNT(*) FROM r;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 1001) SELECT COUNT(*) FROM r;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 1002) SELECT COUNT(*) FROM r;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 5000) SELECT COUNT(*) FROM r;
SHOW WARNINGS;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 100000) SELECT n FROM r LIMIT 5;
-- What a recursive part may hold.
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT MAX(n) + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 GROUP BY n) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT ROW_NUMBER() OVER () + n FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 ORDER BY n) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 LIMIT 10) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 100000 LIMIT 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 100000 LIMIT 3 OFFSET 1) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT DISTINCT n + 1 FROM r WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT r.n + 1 FROM r JOIN wr ON wr.id = r.n WHERE r.n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT r.n + 1 FROM wr LEFT JOIN r ON wr.id = r.n WHERE r.n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT r.n + 1 FROM r LEFT JOIN wr ON wr.id = r.n WHERE r.n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM wr WHERE id IN (SELECT n FROM r) AND id < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < (SELECT COUNT(*) FROM wr)) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT a.n + b.n FROM r AS a JOIN r AS b ON a.n = b.n WHERE a.n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM (SELECT n FROM r) AS d WHERE n < 3) SELECT n FROM r ORDER BY n;
WITH RECURSIVE a (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM b WHERE n < 3), b (n) AS (SELECT n FROM a) SELECT n FROM a ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) SELECT n FROM r WHERE n > 1 ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3 UNION ALL SELECT 5) SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM r WHERE n < 3) CYCLE n RESTRICT SELECT n FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n % 2 + 1 FROM r) CYCLE n RESTRICT SELECT n FROM r ORDER BY n;
-- Without strict mode (to the end of the session).
SET SESSION sql_mode = '';
WITH RECURSIVE r (n, s) AS (SELECT 1, 'a' UNION ALL SELECT n + 1, CONCAT(s, 'b') FROM r WHERE n < 3) SELECT n, s FROM r ORDER BY n;
WITH RECURSIVE r (n) AS (SELECT 1 UNION ALL SELECT n * 1000 FROM r WHERE n < 1000000000000) SELECT COUNT(*), MAX(n) FROM r;
WITH RECURSIVE r (n) AS (SELECT NULL UNION ALL SELECT 1 FROM r WHERE n IS NULL) SELECT n, n IS NULL, LENGTH(n) FROM r ORDER BY n;
